//! Assemble NPC characters into one skinned glTF each, reusing the player pipeline
//! (`assets::player_model::{build_player_skeleton, write_player_gltf}`) without changing it.
//!
//! Recipes come from `data/npc_appearance.tsv` (generated by `.tools/npc_decode.py` from the character recipe table):
//! * `cc` (generic) characters: all parts live in ONE pack, `chara/data/cc/cc.gfpak`, at
//!   `bin/chara/data/cc/model/<base|dress|face>/<stem>/<stem>.<ext>`. The base `cc_base0001_00_young_m.trskl` is the
//!   full biped (74 nodes); dress and face carry extension skeletons with a rig offset, exactly like the player's.
//!   Clips: `bin/chara/data/cc/motion/base/<motion_set>/<motion_set>_<nnnnn>_<name>.tranm`.
//! * `tr` (unique) characters: one pack `chara/data/tr/<stem>.gfpak`, files at `bin/chara/data/tr/<stem>/`, with its own
//!   skeleton; clips `bin/chara/data/tr/<stem>/trNNNN_NN_<nnnnn>_<name>.tranm` (first two stem tokens).
//!
//! `assemble_pack_with` names the model descriptor after the pack FILE stem and resolves every `.tranm` name found in
//! any entry under the part's directory, which fails on the shared cc pack (clip names of all characters). So for each
//! cc part a small sub-pack `<out>/subpacks/<part stem>.gfpak` is written (temp file + rename, never through a link) with only the files the part's model references
//! (trmdl -> trmsh/trmtr/trskl -> trmbf/bntx), payloads copied byte for byte (still Oodle-framed).
//!
//! Usage: npc_export <romfs bin/archive/chara/data> <out dir> --ids id[,id..] [--recipes data/npc_appearance.tsv]
//!        [--cc-pack <cc.gfpak>]
//! Output: `<out>/<id>/npc.gltf` (+ PNG textures). Not applied: body-type mesh scalers (`chara_create_value_list_*`),
//! the real hair/eye/skin colour rule (a SUPPOSED colour is baked only into layered grey albedos, see `npc_options` and
//! `all_layered`), held item, hide-mesh rules, IK, spring bones.

use pla::assets::{
    gfpak::GfPak,
    player_model::{build_player_skeleton, read_skin_color_table, write_player_gltf, PlayerExportOptions},
    pokemon_model::{assemble_pack_with, LayerBlendFormula, PackLayout, PokemonModel},
    tr,
};
use std::{collections::HashMap, env, fs, path::Path, path::PathBuf};

/// Body clips exported when present (motion-set clip suffix, glTF name).
const CLIPS: &[(&str, &str)] = &[("02001_wait01_loop", "idle"), ("02101_walk01_loop", "walk"), ("02121_run01_loop", "run")];

/// Natural hair colours (sRGB). Hair, skin and eye colours of generic characters are chosen at runtime by a rule that is
/// NOT in the files found: this deterministic pick by id is SUPPOSED, only so the grey hair/skin masks do not render
/// white/blue-grey. Named (`tr`) characters keep their own textures untouched.
const HAIR: &[[u8; 3]] = &[[72, 48, 34], [150, 112, 82], [30, 28, 30], [28, 34, 62], [120, 80, 50], [170, 130, 70], [100, 60, 40], [60, 40, 30]];
const HAIR_OLD: &[[u8; 3]] = &[[235, 232, 226], [150, 150, 155], [200, 198, 195]];
const EYES: &[[u8; 3]] = &[[90, 58, 36], [130, 95, 50], [30, 26, 26], [60, 100, 190], [60, 150, 80], [130, 135, 140]];

fn fnv32(s: &str) -> u32 {
    s.bytes().fold(0x811c_9dc5u32, |h, b| (h ^ u32::from(b)).wrapping_mul(0x0100_0193))
}

/// Deterministic SUPPOSED colours for a generic character id.
fn npc_options(id: &str, skin_rows: &[[u8; 3]]) -> PlayerExportOptions {
    let h = fnv32(id);
    let old = id.contains("_old_");
    let hair = if old { HAIR_OLD[(h >> 3) as usize % HAIR_OLD.len()] } else { HAIR[(h >> 3) as usize % HAIR.len()] };
    PlayerExportOptions {
        skip_hidden: false,
        skin_rgb: (!skin_rows.is_empty()).then(|| skin_rows[(h >> 11) as usize % skin_rows.len().min(4)]),
        hair_rgb: Some(hair),
        eye_rgb: Some(EYES[(h >> 17) as usize % EYES.len()]),
        color_variants: false,
        skin_unbaked: false,
    }
}

/// The pack assembler gives every mesh of a model the FIRST material file. Models with several material files (body, face,
/// hairstyle... in separate `.trmtr`) then render with one wrong texture (the doctor in purple hair texture). Point each mesh at the
/// material file that has a block named like its material binding.
fn assign_material_files(model: &mut PokemonModel, notes: &mut Vec<String>) {
    let blocks: Vec<(usize, Vec<String>)> = model
        .materials
        .iter()
        .filter(|m| !m.source_name.to_ascii_lowercase().contains("rare"))
        .map(|m| (m.entry_index, pla::assets::pokemon_material::parse_blocks(&m.raw_bytes).into_iter().map(|b| b.name.to_ascii_lowercase()).collect()))
        .collect();
    if blocks.len() < 2 {
        return;
    }
    let mut changed = 0;
    for mesh in &mut model.meshes {
        let binding = mesh.material_binding.to_ascii_lowercase();
        if let Some((entry, _)) = blocks.iter().find(|(_, names)| names.contains(&binding)) {
            if mesh.material_entry_index != Some(*entry) {
                mesh.material_entry_index = Some(*entry);
                changed += 1;
            }
        }
    }
    notes.push(format!("{} material files, {changed} meshes re-pointed", blocks.len()));
}

/// Synthetic `entry_index` base for the per-block material copies made by [`split_material_blocks`].
const BLOCK_MATERIAL_BASE: usize = 1 << 30;

/// A `.trmtr` holds several blocks (`face_skin`, `face`, `hairstyle`, `eye`...), but `texture_links` is per FILE. When a
/// block has no layer mask (`Standard` shader without `BaseColorLayer*`, e.g. most cc faces and every tr), the material
/// export falls back to the file's FIRST `BaseColorMap`, so hair, eyes and clothes all got one albedo (the face skin on
/// cc faces, the eye/obj/ring albedo on tr packs). Give each mesh a copy of its material whose links are only the
/// textures of its own block (same raw bytes, so the layer-mask and eye bakes are unchanged).
fn split_material_blocks(model: &mut PokemonModel, notes: &mut Vec<String>) {
    let mut copies: Vec<((usize, String), usize)> = Vec::new();
    let mut extra: Vec<pla::assets::pokemon_model::PokemonMaterial> = Vec::new();
    for mesh in &mut model.meshes {
        let Some(index) = mesh.material_entry_index else { continue };
        let binding = mesh.material_binding.to_ascii_lowercase();
        if let Some((_, copy)) = copies.iter().find(|(k, _)| k.0 == index && k.1 == binding) {
            mesh.material_entry_index = Some(*copy);
            continue;
        }
        let Some(material) = model.materials.iter().find(|m| m.entry_index == index) else { continue };
        let blocks = pla::assets::pokemon_material::parse_blocks(&material.raw_bytes);
        let Some(block) = blocks.iter().find(|b| b.name.eq_ignore_ascii_case(&binding)) else { continue };
        let links: Vec<(String, String)> = block
            .textures
            .iter()
            .filter_map(|(file, slot)| {
                let wanted = stem(file).to_ascii_lowercase();
                material.texture_links.iter().find(|(role, name)| role == slot && name.to_ascii_lowercase() == wanted).cloned()
            })
            .collect();
        if links.is_empty() || links == material.texture_links {
            continue;
        }
        let mut copy = material.clone();
        copy.entry_index = BLOCK_MATERIAL_BASE + extra.len();
        copy.texture_links = links;
        copies.push(((index, binding), copy.entry_index));
        mesh.material_entry_index = Some(copy.entry_index);
        extra.push(copy);
    }
    if !extra.is_empty() {
        notes.push(format!("{} per-block material copies", extra.len()));
    }
    model.materials.extend(extra);
}

/// True when every block named `binding`-like (by `is`) in the models has a `LayerMaskMap` + `BaseColorLayer1..4`, i.e.
/// a grey layered albedo like the player's; such blocks are what the SUPPOSED skin/hair colour is meant for. Blocks
/// without layers (unique cc faces) already carry their own colours and must not be tinted again.
/// `mask_only`: only the `LayerMaskMap` is required (the eye bake tints the iris through it).
fn all_layered(models: &[PokemonModel], mask_only: bool, is: impl Fn(&str) -> bool) -> bool {
    let mut any = false;
    for m in models {
        for mat in &m.materials {
            for b in pla::assets::pokemon_material::parse_blocks(&mat.raw_bytes) {
                if !is(&b.name.to_ascii_lowercase()) {
                    continue;
                }
                if b.texture("LayerMaskMap").is_none() || (!mask_only && b.base_color_layers().is_none()) {
                    return false;
                }
                any = true;
            }
        }
    }
    any
}

fn read_recipes(path: &str) -> Result<Vec<HashMap<String, String>>, String> {
    let text = fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?;
    let mut lines = text.lines().filter(|l| !l.starts_with('#'));
    let header: Vec<String> =
        lines.next().unwrap_or_default().split('\t').map(|h| h.split(':').next().unwrap_or("").to_owned()).collect();
    Ok(lines.map(|l| header.iter().cloned().zip(l.split('\t').map(str::to_owned)).collect()).collect())
}

fn stem(file: &str) -> &str {
    file.rsplit_once('.').map_or(file, |(s, _)| s)
}

fn entry(pack_bytes: &[u8], gp: &GfPak, path: &str) -> Result<Option<Vec<u8>>, String> {
    match gp.entry_index_by_path(path)? {
        Some(i) => Ok(Some(gp.decoded_data(pack_bytes, &gp.entries[i])?)),
        None => Ok(None),
    }
}

/// File names with a model extension written inside `bytes`.
fn model_refs(bytes: &[u8]) -> Vec<String> {
    let mut out = Vec::new();
    let mut start = None;
    for (i, &b) in bytes.iter().chain(std::iter::once(&0)).enumerate() {
        let ok = b.is_ascii_alphanumeric() || b == b'_' || b == b'.' || b == b'-';
        match (ok, start) {
            (true, None) => start = Some(i),
            (false, Some(s)) => {
                if let Ok(t) = std::str::from_utf8(&bytes[s..i]) {
                    if [".trmsh", ".trmbf", ".trmtr", ".trskl", ".bntx", ".trmmt"].iter().any(|e| t.ends_with(e)) {
                        out.push(t.to_owned());
                    }
                }
                start = None;
            }
            _ => {}
        }
    }
    out
}

/// Write a GFLXPACK holding only `dir/<part>.trmdl` and the files it references (transitively), payloads copied raw.
fn sub_pack(bytes: &[u8], gp: &GfPak, dir: &str, part: &str, out: &Path) -> Result<usize, String> {
    let mut todo = vec![format!("{part}.trmdl")];
    let mut chosen: Vec<usize> = Vec::new();
    while let Some(name) = todo.pop() {
        let Some(i) = gp.entry_index_by_path(&format!("{dir}/{name}"))? else { continue };
        if chosen.contains(&i) {
            continue;
        }
        chosen.push(i);
        todo.extend(model_refs(&gp.decoded_data(bytes, &gp.entries[i])?));
    }
    // The parser stops reading table offsets at the first u64 that is 0 or >= file size, i.e. the first path hash:
    // put the largest hash first so it can never be mistaken for an offset.
    chosen.sort_by_key(|&i| std::cmp::Reverse(gp.entry_path_hashes[i]));
    let n = chosen.len();
    let table = 0x20 + 8 * n;
    let mut data_at = table + 24 * n;
    let mut head = Vec::with_capacity(data_at);
    head.extend_from_slice(b"GFLXPACK");
    head.extend_from_slice(&0x1000u32.to_le_bytes());
    head.extend_from_slice(&0u32.to_le_bytes());
    head.extend_from_slice(&(n as u32).to_le_bytes());
    head.extend_from_slice(&1u32.to_le_bytes());
    head.extend_from_slice(&(table as u64).to_le_bytes());
    for &i in &chosen {
        head.extend_from_slice(&gp.entry_path_hashes[i].to_le_bytes());
    }
    let mut payload = Vec::new();
    for &i in &chosen {
        let e = &gp.entries[i];
        let raw = gp.data(bytes, e)?;
        head.extend_from_slice(&e.type_id.to_le_bytes());
        head.extend_from_slice(&e.kind.to_le_bytes());
        head.extend_from_slice(&e.checksum.to_le_bytes());
        head.extend_from_slice(&(raw.len() as u32).to_le_bytes());
        head.extend_from_slice(&e.flags.to_le_bytes());
        head.extend_from_slice(&(data_at as u32).to_le_bytes());
        head.extend_from_slice(&e.reserved.to_le_bytes());
        payload.extend_from_slice(raw);
        data_at += raw.len();
    }
    head.extend_from_slice(&payload);
    // Never write THROUGH an existing path (a symlink there would redirect the write into game data):
    // write a fresh temp file next to it and rename it over the path, which replaces the link itself.
    let tmp = out.with_extension("gfpak.tmp");
    if fs::symlink_metadata(&tmp).is_ok() {
        return Err(format!("{} already exists; refusing to overwrite", tmp.display()));
    }
    fs::write(&tmp, head).map_err(|e| format!("{}: {e}", tmp.display()))?;
    fs::rename(&tmp, out).map_err(|e| format!("{}: {e}", out.display()))?;
    Ok(n)
}

fn load_clips(
    pack_bytes: &[u8],
    gp: &GfPak,
    dir: &str,
    set: &str,
    listed: &str,
    notes: &mut Vec<String>,
) -> Vec<(String, tr::TrAnmClip)> {
    let mut out = Vec::new();
    // Clip names do not always repeat the directory name: `motion/base/cb0001_02_adl_f/` holds
    // `cb0001_01_adl_f_*` (see data/npc_animations.tsv). Try the variant number 00..05 of the set name.
    let mut owners = vec![set.to_owned()];
    if set.len() > 10 && set.starts_with("cb") {
        owners.extend((0..6).map(|v| format!("{}{v:02}{}", &set[..7], &set[9..])));
    }
    // Prefer the clip the body controller lists (.tracr, column controller_clips): sets share clips, e.g. the
    // cb0001_02_adl_f controller walks with cb0005_01_kmn_f_02101_walk01_loop.
    for o in listed.split(',').filter_map(|c| c.find("_020").or_else(|| c.find("_021")).map(|i| &c[..i])) {
        if !owners.iter().any(|x| x == o) {
            owners.insert(0, o.to_owned());
        }
    }
    for (suffix, name) in CLIPS {
        let in_list = listed.split(',').find(|c| c.ends_with(suffix)).map(|c| format!("{dir}/{c}.tranm"));
        let path = in_list
            .into_iter()
            .chain(owners.iter().map(|o| format!("{dir}/{o}_{suffix}.tranm")))
            .find(|p| gp.entry_index_by_path(p).ok().flatten().is_some())
            .unwrap_or_else(|| format!("{dir}/{set}_{suffix}.tranm"));
        match entry(pack_bytes, gp, &path) {
            Ok(Some(bytes)) => match tr::TrAnm::parse_tracks(&bytes) {
                Ok(mut clip) => {
                    clip.tracks.retain(|t| t.name != "chara_root_exp");
                    out.push(((*name).to_owned(), clip));
                }
                Err(e) => notes.push(format!("clip {path}: {e}")),
            },
            Ok(None) => notes.push(format!("clip {path}: not in pack")),
            Err(e) => notes.push(format!("clip {path}: {e}")),
        }
    }
    out
}

/// Rig offset (root field 4) of an extension skeleton; `u32::MAX` when absent.
fn rig_offset(bytes: &[u8]) -> u32 {
    let rd = |at: usize| bytes.get(at..at + 4).map(|b| u32::from_le_bytes(b.try_into().unwrap()));
    let rd16 = |at: usize| bytes.get(at..at + 2).map(|b| u16::from_le_bytes(b.try_into().unwrap()));
    (|| {
        let root = rd(0)? as usize;
        let vt = usize::try_from(root as i64 - i64::from(rd(root)? as i32)).ok()?;
        let vsize = rd16(vt)? as usize;
        if vsize < 4 + 2 * 5 {
            return None;
        }
        let off = rd16(vt + 4 + 2 * 4)? as usize;
        (off != 0).then(|| rd(root + off)).flatten()
    })()
    .unwrap_or(u32::MAX)
}

fn export(chara: &Path, cc_pack: &Path, out: &Path, r: &HashMap<String, String>, skin_rows: &[[u8; 3]]) -> Result<String, String> {
    let id = r.get("name").filter(|n| !n.is_empty()).or_else(|| r.get("hash")).ok_or("recipe row without id")?.clone();
    let kind = r.get("kind").map_or("", String::as_str);
    let mut notes = Vec::new();
    let mut models: Vec<PokemonModel> = Vec::new();
    let mut exts: Vec<(String, Vec<u8>)> = Vec::new();
    let (skeleton_bytes, clips) = match kind {
        "cc" => {
            let bytes = fs::read(cc_pack).map_err(|e| format!("{}: {e}", cc_pack.display()))?;
            let gp = GfPak::parse(&bytes)?;
            let base = stem(&r["base_model"]).to_owned();
            let skl = entry(&bytes, &gp, &format!("bin/chara/data/cc/model/base/{base}/{base}.trskl"))?.ok_or("cc base skeleton not found")?;
            let links = out.join("subpacks");
            fs::create_dir_all(&links).map_err(|e| e.to_string())?;
            for (cat, col) in [("base", "base_model"), ("dress", "dress_model"), ("face", "face_model")] {
                let part = stem(r.get(col).map_or("", String::as_str)).to_owned();
                if part.is_empty() {
                    continue;
                }
                let dir = format!("bin/chara/data/cc/model/{cat}/{part}");
                let link = links.join(format!("{part}.gfpak"));
                let files = sub_pack(&bytes, &gp, &dir, &part, &link)?;
                notes.push(format!("{part}: sub-pack {files} files"));
                let layout = PackLayout { base: dir.clone(), mdl_dir: "", anm_dir: "", skeleton: Some(&skl), allow_ik: true };
                let mut model = assemble_pack_with(&link, &layout).map_err(|e| format!("{part}: {e}"))?;
                assign_material_files(&mut model, &mut notes);
                split_material_blocks(&mut model, &mut notes);
                if cat != "base" {
                    if let Some(ext) = entry(&bytes, &gp, &format!("{dir}/{part}.trskl"))? {
                        exts.push((part.clone(), ext));
                    }
                }
                let lod0 = model.meshes.iter().filter(|m| m.lod == Some(0)).count();
                notes.push(format!("{part}: {lod0} LOD0 meshes"));
                if lod0 > 0 {
                    models.push(model);
                }
            }
            let set = r.get("motion_set").cloned().unwrap_or_default();
            let listed = r.get("controller_clips").cloned().unwrap_or_default();
            let mut clips = load_clips(&bytes, &gp, &format!("bin/chara/data/cc/motion/base/{set}"), &set, &listed, &mut notes);
            if !clips.iter().any(|(n, _)| n == "idle") {
                // Held-item / lsp sets (cb1000_00_lsp...) have no standing wait loop: borrow the default adult set of the same
                // body type (SUPPOSED: the game keeps the held-item pose as an extra layer on top of it).
                let fem = r.get("dress_model").is_some_and(|d| d.chars().nth(1) == Some('f'));
                let fallback = if fem { "cb0001_02_adl_f" } else { "cb0001_00_adl_m" };
                notes.push(format!("no idle in {set}: using {fallback}"));
                clips = load_clips(&bytes, &gp, &format!("bin/chara/data/cc/motion/base/{fallback}"), fallback, "", &mut notes);
            }
            (skl, clips)
        }
        "tr" => {
            let pack_stem = stem(&r["pack"]).to_owned();
            let pack = chara.join(format!("tr/{pack_stem}.gfpak"));
            let bytes = fs::read(&pack).map_err(|e| format!("{}: {e}", pack.display()))?;
            let gp = GfPak::parse(&bytes)?;
            let dir = format!("bin/chara/data/tr/{pack_stem}");
            let skl = entry(&bytes, &gp, &format!("{dir}/{pack_stem}.trskl"))?.ok_or("tr skeleton not found")?;
            let layout = PackLayout { base: dir.clone(), mdl_dir: "", anm_dir: "", skeleton: Some(&skl), allow_ik: true };
            let mut model = assemble_pack_with(&pack, &layout).map_err(|e| format!("{pack_stem}: {e}"))?;
            assign_material_files(&mut model, &mut notes);
            split_material_blocks(&mut model, &mut notes);
            notes.push(format!("{pack_stem}: {} LOD0 meshes", model.meshes.iter().filter(|m| m.lod == Some(0)).count()));
            models.push(model);
            // tr clips are named after the first two tokens of the pack stem (`tr0023_00_02001_wait01_loop`).
            let set = pack_stem.get(..9).unwrap_or(&pack_stem).to_owned();
            let listed = r.get("controller_clips").cloned().unwrap_or_default();
            let clips = load_clips(&bytes, &gp, &dir, &set, &listed, &mut notes);
            (skl, clips)
        }
        other => return Err(format!("{id}: unsupported kind {other:?}")),
    };
    // build_player_skeleton expects extension rig ranges in ascending order (face 72 before dress 137).
    // An extension skeleton without a rig offset adds no rig nodes (e.g. df_dress0004_00_vi_middle_f_a): skip it.
    exts.retain(|(part, b)| {
        let keep = rig_offset(b) != u32::MAX;
        if !keep {
            notes.push(format!("{part}: extension skeleton has no rig offset, skipped"));
        }
        keep
    });
    exts.sort_by_key(|(_, b)| rig_offset(b));
    let skel = build_player_skeleton(&skeleton_bytes, &exts)?;
    notes.extend(skel.notes.iter().cloned());
    let mut usable = Vec::new();
    for (name, mut clip) in clips {
        let mut result = pla::assets::gltf_export::animation_tracks_from_tr(&skel.skeleton, &clip);
        if result.is_err() {
            // Some clips animate nodes the selected skeleton does not have (face/eye helpers...): keep only the tracks
            // that resolve by name (partial mapping, SUPPOSED harmless for body idle/walk).
            let before = clip.tracks.len();
            clip.tracks.retain(|t| skel.skeleton.nodes.iter().any(|n| n.name == t.name));
            if clip.tracks.len() < before && !clip.tracks.is_empty() {
                notes.push(format!("clip {name}: dropped {} of {before} tracks absent from the skeleton", before - clip.tracks.len()));
                result = pla::assets::gltf_export::animation_tracks_from_tr(&skel.skeleton, &clip);
            }
        }
        match result {
            Ok(_) => usable.push((name, clip)),
            Err(e) => notes.push(format!("clip {name}: {e}")),
        }
    }
    let dir = out.join(&id);
    fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    let refs: Vec<&PokemonModel> = models.iter().collect();
    let options = if kind == "cc" {
        let mut o = npc_options(&id, skin_rows);
        let skin = |n: &str| matches!(n, "face" | "face_skin" | "body_skin") || n.ends_with("_skin");
        if !all_layered(&models, false, skin) {
            o.skin_rgb = None;
            notes.push("skin not tinted (unlayered skin albedo)".into());
        }
        if !all_layered(&models, false, |n| n.starts_with("hair")) {
            o.hair_rgb = None;
            notes.push("hair not tinted (unlayered hair albedo)".into());
        }
        if !all_layered(&models, true, |n| n == "eye") {
            o.eye_rgb = None;
            notes.push("eye not tinted (no iris layer mask)".into());
        }
        o
    } else {
        PlayerExportOptions::default()
    };
    let gltf = dir.join("npc.gltf");
    if let Err(e) = write_player_gltf(&refs, &skel, &usable, &gltf, Some(LayerBlendFormula::MaskLerp), options) {
        if !e.contains("eye block has no LayerMaskMap") {
            return Err(e);
        }
        // Some eye materials have no layer mask to recolour the iris through: keep every
        // original texture by retrying with the default, uncoloured export options.
        notes.push(format!("eye colour not applied: {e}"));
        write_player_gltf(&refs, &skel, &usable, &gltf, Some(LayerBlendFormula::MaskLerp), PlayerExportOptions::default())?;
    }
    let (mut lo, mut hi) = ([f32::MAX; 3], [f32::MIN; 3]);
    for m in &models {
        for mesh in m.meshes.iter().filter(|m| m.lod == Some(0)) {
            for i in 0..mesh.mesh.vertex_count {
                if let Some(p) = mesh.mesh.position(&mesh.buffer_bytes, i) {
                    for k in 0..3 {
                        lo[k] = lo[k].min(p[k]);
                        hi[k] = hi[k].max(p[k]);
                    }
                }
            }
        }
    }
    let prims: usize = models.iter().map(|m| m.meshes.iter().filter(|x| x.lod == Some(0)).count()).sum();
    Ok(format!(
        "{id}\tok\tparts={} primitives={prims} clips={} height={:.3} m\t{}",
        models.len(),
        usable.len(),
        hi[1] - lo[1],
        notes.join(" | ")
    ))
}

fn main() -> Result<(), String> {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.len() < 2 {
        return Err("usage: npc_export <archive/chara/data> <out dir> --ids a,b [--recipes data/npc_appearance.tsv]".into());
    }
    let chara = PathBuf::from(&args[0]);
    let out = PathBuf::from(&args[1]);
    let opt = |flag: &str| args.iter().position(|a| a == flag).and_then(|i| args.get(i + 1)).cloned();
    // --cc-pack: read the generic-character pack from an explicit file (default <chara>/cc/cc.gfpak).
    let cc_pack = opt("--cc-pack").map_or_else(|| chara.join("cc/cc.gfpak"), PathBuf::from);
    if !cc_pack.is_file() {
        println!("[skip] game data not found under {}", chara.display());
        return Ok(());
    }
    let recipes = read_recipes(&opt("--recipes").unwrap_or_else(|| "data/npc_appearance.tsv".into()))?;
    let ids: Vec<String> = opt("--ids").ok_or("--ids is required")?.split(',').map(str::to_owned).collect();
    // Four skin tones (two groups of the same four rows): SUPPOSED pick by id, see `npc_options`.
    let table_path = chara.join("../../../chara/table/skin_color_table.bin");
    let skin_rows: Vec<[u8; 3]> = fs::read(&table_path)
        .ok()
        .and_then(|b| read_skin_color_table(&b).ok())
        .map(|rows| rows.into_iter().map(|(_, rgb)| rgb).collect())
        .unwrap_or_default();
    for id in &ids {
        match recipes.iter().find(|r| r.get("name") == Some(id) || r.get("hash") == Some(id)) {
            Some(r) => match export(&chara, &cc_pack, &out, r, &skin_rows) {
                Ok(line) => println!("{line}"),
                Err(e) => println!("{id}\tblocked\t{e}"),
            },
            None => println!("{id}\tblocked\tno recipe row"),
        }
    }
    Ok(())
}
